sys_transform_script.script:
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

	// 1. Reject incomplete rows (skip, don't fail the entire import)
    if (!source.u_sku || !source.u_name) {
        log.warn('Row skipped: SKU or name missing (row ' + source.sys_import_row + ')');
        ignore = true;
        return;
    }

    // 2. Clean currency text such as "$1,299.00" -> 1299
    var rawCost = String(source.u_unit_cost).replace(/[^0-9.]/g, '');
    var cost = parseFloat(rawCost);
    if (isNaN(cost)) {
        log.error('Row skipped: invalid unit cost "' + source.u_unit_cost + '" for SKU ' + source.u_sku);
        ignore = true;
        return;
    }
    target.unit_cost = cost;

    // 3. Normalise the choice value to match the choice list ("Laptop " -> "laptop")
    var type = String(source.u_type).trim().toLowerCase();
    var validTypes = ['laptop', 'monitor', 'phone', 'accessory'];
    target.type = validTypes.indexOf(type) > -1 ? type : 'accessory';

    // 4. Numbers: default safely
    target.stock_qty = parseInt(source.u_stock_qty, 10) || 0;
    target.reorder_level = parseInt(source.u_reorder_level, 10) || 5;

    // 5. Insert-only defaults
    if (action === 'insert') {
        target.active = true;
    }

})(source, map, log, target);
